/* ===== Espacio interno del equipo (/admin-login y /gestion/*). La interfaz oculta lo no autorizado; el servidor lo impone. ===== */
const REVIEW_LABEL={draft:'Borrador',in_review:'En revisión',changes_requested:'Cambios solicitados',rejected:'Rechazada',approved:'Aprobada'};
const PUBLIC_LABEL={not_public:'No pública',published:'Publicada',paused:'Retirada',closed:'Cerrada',archived:'Archivada'};
const AWARD_LABEL={pending_confirmation:'Preliminar · pendiente de confirmación',confirmed:'Confirmada',defaulted:'Incumplimiento registrado',offered_to_runner_up:'Ofrecida al segundo oferente',no_bids:'Sin ofertas (desierta)'};
const POST_LABEL={draft:'Borrador',review:'En revisión',scheduled:'Programado',published:'Publicado',archived:'Archivado'};
const LEAD_TYPE={seller:'Venta de propiedad',remate:'Interés en remate',contact:'Contacto',deletion:'Eliminación de datos'};
const LEAD_STATUS={new:'Nueva',assigned:'Asignada',contacted:'Contactada',info_requested:'Información solicitada',qualified:'Calificada',closed:'Cerrada',declined:'No continúa'};
const tag=(text,cls='')=>h`<span class="tag ${cls}">${text}</span>`;
const reviewTag=s=>tag(REVIEW_LABEL[s]||s,{in_review:'warn',approved:'ok',rejected:'bad',changes_requested:'warn'}[s]||'');
const staffShell=(path,title,body,{lead='',actions:acts=''}={})=>h`<div class="workspace"><aside class="staff-side" aria-label="Navegación del equipo"><small>${state.staff.roles.map(r=>ROLE_NAMES[r]).join(' · ')}</small>${staffNav().map(n=>h`<a href="${href(n.path)}" ${(n.path==='/gestion'?path==='/gestion':path.startsWith(n.path))?raw('aria-current="page"'):''}>${icon(n.icon)} ${n.label}${n.path==='/gestion/tareas'&&state.staffTasks?.mine?h` <span class="dot-count inline">${state.staffTasks.mine}</span>`:''}</a>`)}<a href="${href('/gestion/mi-perfil')}" ${path==='/gestion/mi-perfil'?raw('aria-current="page"'):''}>${icon('user')} Mi perfil</a><button class="link-btn on-dark" data-action="staff-logout">${icon('logout')} Cerrar sesión</button></aside><section class="work-main"><div class="work-head"><div><span class="eyebrow">Equipo SeSubasta</span><h1>${title}</h1>${lead?h`<p>${lead}</p>`:''}</div>${acts?h`<div class="button-row">${acts}</div>`:''}</div>${body}</section></div>`;
const staffRoute=(pattern,opts)=>route(pattern,{area:'staff',auth:'staff',server:true,...opts});
const fileUrl=f=>readFile(f);

/* ---------- ADM-01 acceso del equipo con segundo factor ---------- */
let mfaPending=!!session.get('ss-mfa');const setMfa=v=>{mfaPending=v;v?session.set('ss-mfa',1):session.del('ss-mfa')};
route('/admin-login',{title:'Acceso equipo',area:'staff',focus:true,guest:'staff',server:true,view:async({query})=>({title:'Acceso equipo',html:h`<section class="auth-panel staff-login"><span class="eyebrow">Acceso equipo SeSubasta</span>${mfaPending?h`<h1>Confirma tu acceso</h1><p>Enviamos un código de 6 dígitos a tu correo del equipo. Vence en 10 minutos.</p><form data-form="staff-mfa" novalidate><input type="hidden" name="volver" value="${query.volver||''}"><label class="form-field"><span>Código de verificación</span><input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><button class="btn btn-primary btn-block">Verificar e ingresar</button></form><p class="auth-alt"><button class="link-btn" data-action="mfa-restart">Volver a ingresar credenciales</button></p>${devMailHint()}`:h`<h1>Ingresa con tu cuenta interna</h1><p>Uso exclusivo del personal. Las cuentas las crea el Administrador general.</p><form data-form="staff-login" novalidate><input type="hidden" name="volver" value="${query.volver||''}"><label class="form-field"><span>Correo del equipo</span><input name="email" type="email" autocomplete="username" required></label>${pwField('password','Contraseña','current-password')}<button class="btn btn-primary btn-block">Ingresar a gestión</button></form><p class="auth-alt"><a href="${href('/admin-login/restablecer')}">¿Problemas para acceder?</a></p><p class="hint">Entorno local de demostración. Las credenciales de prueba están en LEEME.md.</p>`}</section>`})});
forms['staff-login']=form=>submitWith(form,async d=>{const r=await POST('/api/v1/admin/auth/login',{email:d.email,password:d.password});if(r.mfaRequired){setMfa(true);return render()}state.staff=r.user;toast('Bienvenido al espacio del equipo.','success');navigate(d.volver&&d.volver.startsWith('/gestion')?d.volver:'/gestion',{replace:true})});
forms['staff-mfa']=form=>submitWith(form,async d=>{try{const r=await POST('/api/v1/admin/auth/mfa/verify',{code:d.code});setMfa(false);state.staff=r.user;navigate(d.volver&&d.volver.startsWith('/gestion')?d.volver:'/gestion',{replace:true})}catch(e){if(e.code==='MFA_EXPIRED'||e.status===429){setMfa(false);toast(e.message,'error');return render()}throw e}});
actions['mfa-restart']=()=>{setMfa(false);render()};
route('/admin-login/restablecer',{title:'Recuperar acceso interno',area:'staff',focus:true,server:true,view:async x=>x.query.token?resetView('/api/v1/admin/auth/reset-password','/admin-login')(x):{title:'Recuperar acceso',html:h`<section class="auth-panel staff-login"><h1>Recupera tu acceso interno</h1><p>Si tu correo corresponde a una cuenta activa del equipo, recibirás un enlace de un solo uso.</p><form data-form="staff-forgot" novalidate><label class="form-field"><span>Correo del equipo</span><input name="email" type="email" required></label><button class="btn btn-primary btn-block">Enviar enlace</button></form><p class="auth-alt"><a href="${href('/admin-login')}">Volver</a></p></section>`}});
forms['staff-forgot']=form=>submitWith(form,async d=>{await POST('/api/v1/admin/auth/forgot-password',d);form.outerHTML=toHtml(h`<div class="notice success">${icon('check')} Si la cuenta existe, enviamos el enlace.</div>${devMailHint()}`)});
route('/admin-login/invitacion',{title:'Activa tu cuenta',area:'staff',focus:true,server:true,view:async({query})=>{let inv;try{inv=await GET('/api/v1/admin/auth/invite?token='+encodeURIComponent(query.token||''))}catch(e){return {title:'Invitación no válida',html:h`<section class="auth-panel staff-login"><h1>La invitación no es válida</h1><p>${e.message} Pide al Administrador general una nueva invitación.</p></section>`}}
 return {title:'Activa tu cuenta',html:h`<section class="auth-panel staff-login"><span class="eyebrow">Invitación al equipo</span><h1>Activa tu cuenta</h1><p>${inv.name} · ${inv.email}<br>Rol asignado: ${inv.roles.join(', ')}</p><form data-form="staff-invite" novalidate><input type="hidden" name="token" value="${query.token}">${pwField('password','Crea tu contraseña','new-password','Mínimo 10 caracteres, con letras y al menos un número.')}${pwField('password2','Repite la contraseña','new-password')}<button class="btn btn-primary btn-block">Activar cuenta</button></form></section>`}}});
forms['staff-invite']=form=>submitWith(form,async d=>{await POST('/api/v1/admin/auth/accept-invite',d);form.outerHTML=toHtml(h`<div class="notice success">${icon('check')} Cuenta activada.</div><a class="btn btn-primary btn-block" href="${href('/admin-login')}">Ingresar</a>`)});

/* ---------- ADM-02 resumen por rol ---------- */
staffRoute('/gestion',{title:'Resumen',view:async({path})=>{const s=await GET('/api/v1/admin/summary');const card=(label,val,link,note='')=>h`<a class="metric" href="${href(link)}"><small>${label}</small><strong>${val}</strong>${note?h`<em>${note}</em>`:''}</a>`;const tasks=[];
 if(hasRole('internal_contributor'))tasks.push(h`<li><a href="${href('/gestion/propiedades?review=changes_requested')}">${s.properties.changes_requested} fichas con cambios solicitados</a></li>`,h`<li><a href="${href('/gestion/propiedades?review=draft')}">${s.properties.draft} borradores por completar</a></li>`);
 if(hasRole('legal'))tasks.push(h`<li><a href="${href('/gestion/revisiones')}">${s.legalPending} fichas con bloque legal pendiente</a></li>`);
 if(state.staff.roles.includes('general_admin'))tasks.push(h`<li><a href="${href('/gestion/revisiones?status=in_review')}">${s.properties.in_review} fichas esperan tu decisión de publicación</a></li>`);
 if(hasRole('operator'))tasks.push(h`<li><a href="${href('/gestion/remates')}">${s.awardsPending} resultados por confirmar</a></li>`,h`<li><a href="${href('/gestion/solicitudes?status=new')}">${s.leads.new} solicitudes nuevas</a></li>`);
 if(hasRole('content_editor'))tasks.push(h`<li><a href="${href('/gestion/blog?status=draft')}">${s.posts.draft} artículos en borrador</a></li>`);
 return {title:'Resumen',html:staffShell(path,'Resumen de gestión',h`<div class="metric-grid">${card('Mis tareas abiertas',s.tasks.mine,'/gestion/tareas',s.tasks.overdue?`${s.tasks.overdue} vencidas`:'')}${hasRole('internal_contributor','legal')?h`${card('En revisión',s.properties.in_review,'/gestion/revisiones')}${card('Borradores',s.properties.draft,'/gestion/propiedades?review=draft')}${card('Publicadas',s.properties.published,'/gestion/propiedades?public=published')}`:''}${hasRole('operator')?h`${card('Subastas en vivo',s.auctions.open,'/gestion/remates',`${s.viewers} espectadores conectados`)}${card('Próximas',s.auctions.scheduled,'/gestion/remates')}${card('Suspendidas',s.auctions.paused,'/gestion/remates')}${card('Resultados por confirmar',s.awardsPending,'/gestion/remates')}${card('Intentos rechazados (24 h)',s.rejectedAttempts24h,'/gestion/ofertas?result=rejected')}${card('Solicitudes nuevas',s.leads.new,'/gestion/solicitudes')}`:''}${hasRole('content_editor')?h`${card('Artículos publicados',s.posts.published,'/gestion/blog?status=published')}${card('Programados',s.posts.scheduled,'/gestion/blog?status=scheduled')}`:''}</div>
  <div class="panel"><h2>Tus tareas</h2>${tasks.length?h`<ul class="task-list">${tasks}</ul>`:h`<p>No tienes tareas pendientes.</p>`}</div><p class="source-note">Este resumen no muestra montos pendientes de aprobación: el motor acepta o rechaza cada monto automáticamente.</p>`,{lead:`Hola, ${state.staff.name}.`})}}});

/* ---------- ADM-03 listado de propiedades ---------- */
staffRoute('/gestion/propiedades',{title:'Propiedades',roles:['internal_contributor','legal'],view:async({path,query})=>{const qs=new URLSearchParams(Object.entries(query).filter(([,v])=>v));const r=await GET('/api/v1/admin/properties?'+qs);const canCreate=hasRole('internal_contributor');
 return {title:'Propiedades',html:staffShell(path,'Propiedades',h`<form class="toolbar" data-form="prop-filter" data-nodraft><label class="form-field"><span>Buscar</span><input name="q" value="${query.q||''}" placeholder="ID, título o comuna"></label><label class="form-field"><span>Revisión</span><select name="review"><option value="">Todas</option>${Object.entries(REVIEW_LABEL).map(([k,v])=>h`<option value="${k}" ${query.review===k?'selected':''}>${v}</option>`)}</select></label><label class="form-field"><span>Estado público</span><select name="public"><option value="">Todos</option>${Object.entries(PUBLIC_LABEL).map(([k,v])=>h`<option value="${k}" ${query.public===k?'selected':''}>${v}</option>`)}</select></label><label class="form-check"><input type="checkbox" name="mine" ${query.mine?'checked':''}> <span>Solo mis fichas</span></label><button class="btn btn-dark">Filtrar</button></form>
  ${r.items.length?h`<div class="table-wrap"><table class="responsive-table"><thead><tr><th>ID</th><th>Propiedad</th><th>Revisión</th><th>Público</th><th>Actualizada</th><th>Creador</th><th>Legal</th><th><span class="visually-hidden">Acciones</span></th></tr></thead><tbody>${r.items.map(p=>h`<tr><td data-label="ID">${p.publicId}</td><td data-label="Propiedad"><strong>${p.title}</strong><br><small>${p.commune||'Sin comuna'} · ${p.type}</small></td><td data-label="Revisión">${reviewTag(p.reviewStatus)}${p.hasPendingChanges?h`<br><small>Cambios sin publicar</small>`:''}</td><td data-label="Público">${tag(PUBLIC_LABEL[p.publicStatus],p.publicStatus==='published'?'ok':'')}</td><td data-label="Actualizada">${fmt.short(p.updatedAt)}</td><td data-label="Creador">${p.createdByName}</td><td data-label="Legal">${p.assignedLegalName}<br><small>${p.legalComplete?'Bloque completo':'Pendiente'}</small></td><td data-label="Acciones"><a class="btn btn-outline btn-sm" href="${href('/gestion/propiedades/'+p.id)}">Abrir</a></td></tr>`)}</tbody></table></div>`:h`<div class="empty-state"><p>No hay fichas con estos filtros.</p></div>`}`,{lead:'Fichas internas. Guardar nunca publica: solo el Administrador general aprueba y publica.',actions:canCreate?h`<button class="btn btn-primary" data-action="prop-new">+ Nueva propiedad</button>`:''})}}});
forms['prop-filter']=form=>{const d=formData(form);navigate('/gestion/propiedades?'+new URLSearchParams(Object.entries({...d,mine:d.mine?'1':''}).filter(([,v])=>v)))};
actions['prop-new']=async()=>{try{const r=await POST('/api/v1/admin/properties',{title:'Nueva propiedad'});toast('Borrador privado creado.','success');navigate('/gestion/propiedades/'+r.property.id)}catch(e){toast(e.message,'error')}};

/* ---------- ADM-04 crear / editar propiedad por pestañas ---------- */
const PROP_TABS=[['datos','Datos del inmueble'],['fotos','Fotografías'],['legal','Antecedentes legales'],['condiciones','Condiciones del remate'],['seo','SEO'],['vista','Previsualización'],['historial','Historial']];
let currentProp=null;
staffRoute('/gestion/propiedades/:id',{title:'Ficha interna',roles:['internal_contributor','legal'],view:async({params,query,path})=>{const r=await GET('/api/v1/admin/properties/'+params.id);const p=r.property;currentProp=p;const tab=PROP_TABS.some(t=>t[0]===query.tab)?query.tab:'datos';const P=p.permissions;const C=r.communes;
 const lock=(ok,who)=>ok?'':h`<p class="notice">${icon('lock')} ${who}</p>`;const dis=ok=>ok?'':raw('disabled');
 const checklist=h`<div class="completeness"><div><h3>Bloque general <small>Colaborador · ${p.createdByName}</small></h3><ul>${p.completeness.general.map(c=>h`<li class="${c.ok?'ok':'miss'}">${icon(c.ok?'check':'alert')} ${c.name}</li>`)}</ul></div><div><h3>Bloque legal <small>Legal · ${p.assignedLegalName}</small></h3><ul>${p.completeness.legal.map(c=>h`<li class="${c.ok?'ok':'miss'}">${icon(c.ok?'check':'alert')} ${c.name}</li>`)}</ul></div></div>`;
 const content={
  datos:h`<form data-form="prop-general" class="panel" novalidate>${lock(P.general,'Solo el colaborador responsable o el Administrador general editan estos datos.')}<fieldset ${dis(P.general)}><div class="field-grid"><label class="form-field"><span>Título público *</span><input name="title" value="${p.title}" required maxlength="140"></label><label class="form-field"><span>Tipo *</span><select name="type">${['Casa','Departamento','Terreno','Oficina','Local comercial','Bodega','Otro'].map(t=>h`<option ${p.type===t?'selected':''}>${t}</option>`)}</select></label></div>
   <div class="field-grid"><label class="form-field"><span>Comuna *</span><select name="commune"><option value="">Selecciona</option>${Object.keys(C).sort((a,b)=>a.localeCompare(b,'es')).map(c=>h`<option ${p.commune===c?'selected':''}>${c}</option>`)}</select><small class="hint">Define la región y la ubicación aproximada del mapa.</small></label><label class="form-field"><span>Dirección exacta (privada)</span><input name="exactAddress" value="${p.exactAddress||''}"><small class="hint">Nunca se publica.</small></label></div>
   <div class="field-grid four"><label class="form-field"><span>Superficie útil m² *</span><input name="area" type="number" min="1" value="${p.area??''}"></label><label class="form-field"><span>Terreno m²</span><input name="plot" type="number" min="0" value="${p.plot??''}"></label><label class="form-field"><span>Dormitorios</span><input name="rooms" type="number" min="0" value="${p.rooms??''}"></label><label class="form-field"><span>Baños</span><input name="baths" type="number" min="0" value="${p.baths??''}"></label><label class="form-field"><span>Estacionamientos</span><input name="parking" type="number" min="0" value="${p.parking??''}"></label><label class="form-field"><span>Gastos comunes (CLP)</span><input name="expenses" type="number" min="0" value="${p.expenses??''}"></label><label class="form-field"><span>Ocupación</span><select name="occupancy">${['Desocupada','Ocupada','Por confirmar'].map(o=>h`<option ${p.occupancy===o?'selected':''}>${o}</option>`)}</select></label></div>
   <label class="form-field"><span>Descripción editorial * <small>(mínimo 40 caracteres)</small></span><textarea name="description" rows="5">${p.description}</textarea></label>${state.staff.roles.includes('general_admin')?h`<label class="form-field"><span>Responsable Legal</span><select name="assignedLegal"><option value="">Sin asignar</option>${r.legalUsers.map(u=>h`<option value="${u.id}" ${p.assignedLegal===u.id?'selected':''}>${u.name}</option>`)}</select></label>`:''}<button class="btn btn-dark">Guardar borrador privado</button></fieldset></form>`,
  fotos:h`<div class="panel">${lock(P.general,'Solo el colaborador responsable o el Administrador general gestionan las fotografías.')}<ul class="media-admin">${p.media.map((m,i)=>h`<li><img src="${m.url}" alt="${m.alt}" width="160" height="106"><form data-form="media-alt" data-key="${m.key}" data-nodraft><label class="form-field"><span>Texto alternativo ${i===0?'(foto principal)':''}</span><input name="alt" value="${m.alt}" ${dis(P.general)}></label></form><div class="button-row">${P.general?h`<button class="btn btn-outline btn-sm" data-action="media-move" data-key="${m.key}" data-dir="-1" ${i===0?'disabled':''} aria-label="Subir">↑</button><button class="btn btn-outline btn-sm" data-action="media-move" data-key="${m.key}" data-dir="1" ${i===p.media.length-1?'disabled':''} aria-label="Bajar">↓</button><button class="btn btn-outline btn-sm" data-action="media-alt-save" data-key="${m.key}">Guardar texto</button><button class="btn btn-danger-outline btn-sm" data-action="media-remove" data-key="${m.key}">Quitar</button>`:''}</div></li>`)}</ul>${p.media.length?'':h`<p>Aún no hay fotografías. La primera será la foto principal.</p>`}
   ${P.general?h`<form data-form="media-upload" class="upload-box" novalidate><h3>Subir fotografía</h3><label class="form-field"><span>Imagen (JPG, PNG o WebP, máximo 4 MB)</span><input name="file" type="file" accept="image/jpeg,image/png,image/webp" required></label><label class="form-field"><span>Texto alternativo *</span><input name="alt" required minlength="5" placeholder="Describe lo que muestra la imagen"></label><button class="btn btn-dark">${icon('upload')} Subir</button><p class="hint">Usa fotografías autorizadas y fieles de la propiedad. No subas imágenes generadas por IA ni de bancos como si fueran reales.</p></form>`:''}</div>`,
  legal:h`<div class="panel">${lock(P.legal,'Solo el rol Legal asignado (o el Administrador general) carga y gestiona los antecedentes jurídicos.')}<h2>Documentos</h2>${p.documents.length?h`<ul class="doc-admin">${p.documents.map(d=>h`<li><a href="/api/v1/admin/documents/${d.id}" target="_blank" rel="noopener">${icon('file')} ${d.name}</a><small>${d.type} · ${fmt.short(d.at)} · ${d.visibility==='public'?'Público (autorizado)':'Privado'}</small><div class="button-row">${state.staff.roles.includes('general_admin')?h`<button class="btn btn-outline btn-sm" data-action="doc-visibility" data-doc="${d.id}" data-value="${d.visibility==='public'?'private':'public'}">${d.visibility==='public'?'Volver a privado':'Autorizar como público'}</button>`:''}${P.legal?h`<button class="btn btn-danger-outline btn-sm" data-action="doc-remove" data-doc="${d.id}">Quitar</button>`:''}</div></li>`)}</ul>`:h`<p>Sin documentos cargados.</p>`}
   ${P.legal?h`<form data-form="doc-upload" class="upload-box" novalidate><h3>Cargar antecedente</h3><label class="form-field"><span>Archivo (PDF, JPG o PNG, máximo 8 MB)</span><input name="file" type="file" accept="application/pdf,image/jpeg,image/png" required></label><div class="field-grid"><label class="form-field"><span>Clasificación</span><select name="type"><option>Antecedente legal</option><option>Certificado</option><option>Bases</option><option>Otro</option></select></label><label class="form-field"><span>Nombre visible</span><input name="name" placeholder="Ej.: Certificado de dominio vigente.pdf"></label></div><label class="form-field"><span>Nota</span><input name="note"></label><button class="btn btn-dark">${icon('upload')} Cargar documento privado</button><p class="hint">Todo documento queda privado. Solo el Administrador general puede autorizar uno como público.</p></form>
   <form data-form="prop-legal" class="upload-box" novalidate><h3>Observación jurídica</h3><label class="form-field"><span>Antecedentes revisados, faltantes o advertencias</span><textarea name="legalNotes" rows="4">${p.legalNotes||''}</textarea></label><label class="form-check"><input type="checkbox" name="legalComplete" ${p.legalComplete?'checked':''}> <span>Marco el bloque legal como completo para esta versión.</span></label><button class="btn btn-dark">Guardar bloque legal</button></form>`:h`<p><strong>Observación jurídica:</strong> ${p.legalNotes||'Sin observaciones.'}</p>`}</div>`,
  condiciones:h`<form data-form="prop-conditions" class="panel" novalidate>${lock(P.general,'Solo el colaborador responsable o el Administrador general proponen las condiciones.')}${p.auction&&p.auction.totalBids?h`<p class="notice warn">${icon('lock')} La subasta ya tiene montos registrados: sus reglas no se pueden cambiar.</p>`:''}<fieldset ${dis(P.general&&!(p.auction&&p.auction.totalBids))}><div class="field-grid"><label class="form-field"><span>Inicio · hora de Chile *</span><input name="opensAt" type="datetime-local" value="${toLocalInput(p.conditions.opensAt)}"></label><label class="form-field"><span>Cierre fijo · hora de Chile *</span><input name="closesAt" type="datetime-local" value="${toLocalInput(p.conditions.closesAt)}"></label></div><div class="field-grid"><label class="form-field"><span>Monto inicial (UF) *</span><input name="initialUF" type="number" min="0" step="0.01" value="${p.conditions.initialUF??''}"></label><label class="form-field"><span>Incremento mínimo (UF) *</span><input name="incrementUF" type="number" min="0.01" step="0.01" value="${p.conditions.incrementUF??''}"></label></div><p class="hint">Unidad contractual: UF. El cierre es fijo, sin extensión automática. Las condiciones se aplican al aprobar la publicación.</p><button class="btn btn-dark">Guardar condiciones</button></fieldset>${p.auction?h`<p class="source-note">Subasta vigente #${p.auction.id}: ${STATUS_LABEL[p.auction.status]} · cierre ${fmt.dateTime(p.auction.end)} · ${p.auction.totalBids} registros.</p>`:''}</form>`,
  seo:h`<form data-form="prop-seo" class="panel" novalidate><fieldset ${dis(P.general)}><label class="form-field"><span>URL (slug)</span><input name="slug" value="${p.slug}"><small class="hint">/remates/${p.slug}</small></label><label class="form-field"><span>Título SEO <small data-counter="seoTitle">${(p.seo.title||'').length}/65</small></span><input name="seoTitle" value="${p.seo.title||''}" maxlength="65" data-count="65"></label><label class="form-field"><span>Meta descripción <small data-counter="seoDescription">${(p.seo.description||'').length}/160</small></span><textarea name="seoDescription" maxlength="160" data-count="160" rows="3">${p.seo.description||''}</textarea></label><p class="hint">Las fichas que no están publicadas no se indexan y no aparecen en el sitemap.</p><button class="btn btn-dark">Guardar SEO</button></fieldset></form>`,
  vista:h`<div class="panel"><p class="notice">${icon('eye')} Vista previa privada de esta versión. No es pública hasta que el Administrador general la apruebe.</p><div class="property-list compact">${propertyCard({...p,publicLocation:p.publicLocation||'Comuna sin definir',media:p.media,auction:p.auction,auctionId:p.auctionId||0})}</div>${p.publicStatus==='published'?h`<a class="btn btn-outline" href="/remates/${p.slug}" target="_blank" rel="noopener">Abrir versión pública actual</a>`:''}</div>`,
  historial:h`<div class="panel"><ol class="timeline">${p.history.slice().reverse().map(x=>h`<li><strong>${{created:'Creada',submitted:'Enviada a revisión',published:'Aprobada y publicada',changes_requested:'Cambios solicitados',rejected:'Rechazada',new_version:'Nueva versión privada',unpublished:'Retirada del catálogo',republished:'Republicada'}[x.action]||x.action}</strong> · versión ${x.version} · ${fmt.dateTime(x.at)} · ${x.byName}${x.reason?h`<br><small>${x.reason}</small>`:''}</li>`)}</ol></div>`};
 const isAdmin=state.staff.roles.includes('general_admin');
 return {title:p.title,html:h`${staffShell('/gestion/propiedades',p.title,h`<div class="prop-status">${reviewTag(p.reviewStatus)} ${tag(PUBLIC_LABEL[p.publicStatus],p.publicStatus==='published'?'ok':'')} <span>${p.publicId} · versión ${p.version}</span>${p.hasPublicVersion&&p.reviewStatus!=='approved'?h` <span class="tag warn">La versión pública anterior sigue visible hasta la decisión</span>`:''}</div>${checklist}
  <nav class="tabs" aria-label="Secciones de la ficha">${PROP_TABS.map(([k,l])=>h`<a href="${href(`/gestion/propiedades/${p.id}?tab=${k}`)}" data-replace ${k===tab?raw('aria-current="page"'):''}>${l}</a>`)}</nav>${content[tab]}`,
  {lead:`Creada por ${p.createdByName}. Guardar mantiene la ficha privada.`,actions:h`<button class="btn btn-outline" data-action="task-new" data-link-path="/gestion/propiedades/${p.id}" data-link-label="${p.publicId} · ${p.title}">${icon('check')} Asignar tarea</button>${p.permissions.requestReview?h`<button class="btn btn-primary" data-action="prop-review" ${p.completeness.ready?'':raw('aria-describedby="missingHelp"')}>Solicitar revisión</button>`:''}${isAdmin&&p.reviewStatus==='in_review'?h`<a class="btn btn-primary" href="${href('/gestion/revisiones/'+p.id)}">Ir a decisión de publicación</a>`:''}${hasRole('internal_contributor')?h`<button class="btn btn-outline" data-action="prop-duplicate">Duplicar</button>`:''}${isAdmin&&p.publicStatus==='published'?h`<button class="btn btn-danger-outline" data-action="prop-visibility" data-value="withdraw">Retirar del catálogo</button>`:''}${isAdmin&&p.publicStatus==='paused'&&p.hasPublicVersion?h`<button class="btn btn-outline" data-action="prop-visibility" data-value="republish">Republicar versión aprobada</button>`:''}${isAdmin&&p.publicStatus!=='archived'?h`<button class="btn btn-outline" data-action="prop-visibility" data-value="archive">Archivar</button>`:''}`})}${p.completeness.ready?'':h`<p id="missingHelp" class="visually-hidden">Faltan: ${p.completeness.missing.join(', ')}</p>`}`,
  after:root=>{$$('[data-count]',root).forEach(el=>el.addEventListener('input',()=>{const c=$(`[data-counter="${el.name}"]`,root);if(c)c.textContent=el.value.length+'/'+el.dataset.count}))}}}});
const reloadProp=r=>{currentProp=r.property;render({keepScroll:true})};
const propSave=(body,msg='Cambios guardados como borrador privado.')=>async()=>{const r=await PATCH('/api/v1/admin/properties/'+currentProp.id,body);toast(msg,'success');reloadProp(r)};
forms['prop-general']=form=>submitWith(form,async d=>{const r=await PATCH('/api/v1/admin/properties/'+currentProp.id,d);clearDraft('prop-general');toast('Datos guardados como borrador privado.','success');reloadProp(r)});
forms['prop-legal']=form=>submitWith(form,async d=>{const r=await PATCH('/api/v1/admin/properties/'+currentProp.id,{legalNotes:d.legalNotes,legalComplete:d.legalComplete});clearDraft('prop-legal');toast('Bloque legal guardado.','success');reloadProp(r)});
forms['prop-conditions']=form=>submitWith(form,async d=>{const r=await PATCH('/api/v1/admin/properties/'+currentProp.id,{conditions:{opensAt:fromLocalInput(d.opensAt),closesAt:fromLocalInput(d.closesAt),initialUF:d.initialUF,incrementUF:d.incrementUF}});clearDraft('prop-conditions');toast('Condiciones guardadas.','success');reloadProp(r)});
forms['prop-seo']=form=>submitWith(form,async d=>{const r=await PATCH('/api/v1/admin/properties/'+currentProp.id,{slug:d.slug,seo:{title:d.seoTitle,description:d.seoDescription}});clearDraft('prop-seo');toast('SEO guardado.','success');reloadProp(r)});
forms['media-upload']=form=>submitWith(form,async d=>{const f=form.file.files[0];if(!f)throw new ApiError(422,{message:'Selecciona una imagen.',fields:{file:'Selecciona una imagen.'}});if(f.size>4e6)throw new ApiError(422,{message:'La imagen supera 4 MB.',fields:{file:'La imagen supera 4 MB.'}});const r=await POST(`/api/v1/admin/properties/${currentProp.id}/media`,{file:await fileUrl(f),alt:d.alt});toast('Fotografía subida (privada hasta publicar).','success');reloadProp(r)});
forms['media-alt']=()=>{};
actions['media-alt-save']=async el=>{const input=$(`form[data-key="${el.dataset.key}"] [name=alt]`);try{reloadProp(await PATCH(`/api/v1/admin/properties/${currentProp.id}/media`,{key:el.dataset.key,alt:input.value}));toast('Texto alternativo guardado.','success')}catch(e){toast(e.message,'error')}};
actions['media-move']=async el=>{const keys=currentProp.media.map(m=>m.key);const i=keys.indexOf(el.dataset.key),j=i+Number(el.dataset.dir);[keys[i],keys[j]]=[keys[j],keys[i]];try{reloadProp(await PATCH(`/api/v1/admin/properties/${currentProp.id}/media`,{order:keys}))}catch(e){toast(e.message,'error')}};
actions['media-remove']=async el=>{const c=await confirmDialog({title:'Quitar fotografía',text:'La imagen dejará de formar parte de esta ficha.',confirm:'Quitar',danger:true});if(!c.ok)return;try{reloadProp(await PATCH(`/api/v1/admin/properties/${currentProp.id}/media`,{remove:el.dataset.key}))}catch(e){toast(e.message,'error')}};
forms['doc-upload']=form=>submitWith(form,async d=>{const f=form.file.files[0];if(!f)throw new ApiError(422,{message:'Selecciona un archivo.',fields:{file:'Selecciona un archivo.'}});if(f.size>8e6)throw new ApiError(422,{message:'El archivo supera 8 MB.',fields:{file:'El archivo supera 8 MB.'}});const r=await POST(`/api/v1/admin/properties/${currentProp.id}/documents`,{file:await fileUrl(f),name:d.name||f.name,type:d.type,note:d.note});toast('Documento privado cargado.','success');reloadProp(r)});
actions['doc-visibility']=async el=>{const pub=el.dataset.value==='public';const c=await confirmDialog({title:pub?'Autorizar documento como público':'Volver a privado',text:pub?'El documento quedará disponible en la ficha pública cuando apruebes la versión. Confirma que fue revisado y su difusión está autorizada.':'El documento dejará de estar disponible públicamente.',confirm:pub?'Autorizar':'Volver a privado'});if(!c.ok)return;try{reloadProp(await PATCH(`/api/v1/admin/properties/${currentProp.id}/documents/${el.dataset.doc}`,{visibility:el.dataset.value}))}catch(e){toast(e.message,'error')}};
actions['doc-remove']=async el=>{const c=await confirmDialog({title:'Quitar documento',text:'El documento se retirará del expediente.',confirm:'Quitar',danger:true});if(!c.ok)return;try{reloadProp(await PATCH(`/api/v1/admin/properties/${currentProp.id}/documents/${el.dataset.doc}`,{remove:true}))}catch(e){toast(e.message,'error')}};
actions['prop-review']=async()=>{if(!currentProp.completeness.ready)return toast('Faltan datos: '+currentProp.completeness.missing.join(', '),'error');const c=await confirmDialog({title:'Solicitar revisión',text:'Se congelará esta versión y se enviará al Administrador general. No podrás editarla mientras esté en revisión.',confirm:'Enviar a revisión'});if(!c.ok)return;try{reloadProp(await POST(`/api/v1/admin/properties/${currentProp.id}/request-review`));toast('Enviada a revisión.','success')}catch(e){toast(e.message,'error')}};
actions['prop-duplicate']=async()=>{try{const r=await POST(`/api/v1/admin/properties/${currentProp.id}/duplicate`);toast('Copia creada como borrador.','success');navigate('/gestion/propiedades/'+r.property.id)}catch(e){toast(e.message,'error')}};
actions['prop-visibility']=async el=>{const v=el.dataset.value;const c=await confirmDialog({title:{withdraw:'Retirar del catálogo',archive:'Archivar ficha',republish:'Republicar versión aprobada'}[v],text:v==='republish'?'La última versión aprobada volverá a ser pública.':'La ficha dejará de mostrarse en el catálogo público. El historial se conserva.',confirm:'Confirmar',danger:v!=='republish',reason:true});if(!c.ok)return;try{reloadProp(await POST(`/api/v1/admin/properties/${currentProp.id}/visibility`,{action:v,reason:c.reason}));toast('Estado actualizado.','success')}catch(e){toast(e.message,'error')}};

/* ---------- ADM-09 cola de revisión y ADM-10 expediente y decisión ---------- */
staffRoute('/gestion/revisiones',{title:'Revisiones',roles:['internal_contributor','legal'],view:async({path,query})=>{const r=await GET('/api/v1/admin/reviews'+(query.status?'?status='+query.status:''));const admin=state.staff.roles.includes('general_admin');
 return {title:'Revisiones',html:staffShell(path,'Cola de revisión',h`<div class="filters">${[['','Todas'],['in_review','En revisión'],['changes_requested','Cambios solicitados'],['draft','Borradores'],['rejected','Rechazadas']].map(([v,l])=>h`<a class="chip ${(query.status||'')===v?'active':''}" href="${href('/gestion/revisiones'+(v?'?status='+v:''))}" data-replace>${l}</a>`)}</div>
  ${r.items.length?h`<div class="table-wrap"><table class="responsive-table"><thead><tr><th>ID</th><th>Propiedad</th><th>Enviada</th><th>Solicitante</th><th>Legal</th><th>Versión</th><th>Estado</th><th><span class="visually-hidden">Acción</span></th></tr></thead><tbody>${r.items.map(p=>h`<tr><td data-label="ID">${p.publicId}</td><td data-label="Propiedad"><strong>${p.title}</strong><br><small>${p.commune} · ${p.type}</small></td><td data-label="Enviada">${p.requestedAt?fmt.short(p.requestedAt):'—'}</td><td data-label="Solicitante">${p.requestedBy}</td><td data-label="Legal">${p.legal}<br><small>${p.legalComplete?'Completo':'Pendiente'}</small></td><td data-label="Versión">${p.version}</td><td data-label="Estado">${reviewTag(p.reviewStatus)}${p.ready?'':h`<br><small>Incompleta</small>`}</td><td data-label="Acción">${admin&&p.reviewStatus==='in_review'?h`<a class="btn btn-primary btn-sm" href="${href('/gestion/revisiones/'+p.id)}">Abrir expediente</a>`:h`<a class="btn btn-outline btn-sm" href="${href('/gestion/propiedades/'+p.id)}">Abrir ficha</a>`}</td></tr>`)}</tbody></table></div>`:h`<div class="empty-state"><p>No hay fichas en esta cola.</p></div>`}`,{lead:admin?'Revisa los expedientes enviados y decide su publicación.':'Completa tu bloque. Solo el Administrador general aprueba y publica.'})}}});
const DIFF_FIELDS=[['title','Título'],['type','Tipo'],['publicLocation','Ubicación'],['area','Superficie útil'],['plot','Terreno'],['rooms','Dormitorios'],['baths','Baños'],['parking','Estacionamientos'],['occupancy','Ocupación'],['expenses','Gastos comunes'],['description','Descripción']];
staffRoute('/gestion/revisiones/:id',{title:'Expediente',roles:['general_admin'],view:async({params})=>{const r=await GET('/api/v1/admin/reviews/'+params.id);const p=r.property;currentProp=p;const prev=r.previous,sub=r.submitted||p;
 return {title:'Expediente '+p.publicId,html:staffShell('/gestion/revisiones','Expediente y decisión',h`<div class="prop-status">${reviewTag(p.reviewStatus)} <span>${p.publicId} · versión enviada ${p.submittedVersion} · ${p.title}</span></div>
  <div class="columns"><div><div class="panel"><h2>Datos visibles al publicar</h2><table class="diff"><thead><tr><th>Campo</th><th>Versión pública actual</th><th>Versión enviada</th></tr></thead><tbody>${DIFF_FIELDS.map(([k,l])=>{const a=prev?.[k],b=sub[k];return h`<tr class="${prev&&String(a??'')!==String(b??'')?'changed':''}"><th scope="row">${l}</th><td>${prev?(a??'—'):'Sin versión pública'}</td><td>${b??'—'}</td></tr>`})}</tbody></table></div>
   <div class="panel"><h2>Fotografías</h2><div class="thumb-row">${p.media.map(m=>h`<figure><img src="${m.url}" alt="${m.alt}" width="160" height="106"><figcaption>${m.alt}</figcaption></figure>`)}</div></div>
   <div class="panel"><h2>Antecedentes legales (privados)</h2><p>${p.legalNotes||'Sin observaciones.'}</p><ul class="doc-admin">${p.documents.map(d=>h`<li><a href="/api/v1/admin/documents/${d.id}" target="_blank" rel="noopener">${icon('file')} ${d.name}</a><small>${d.type} · ${d.visibility==='public'?'Autorizado como público':'Privado'}</small></li>`)}</ul></div>
   <div class="panel"><h2>Condiciones del remate</h2><dl class="review-list"><div><dt>Inicio</dt><dd>${fmt.dateTime(p.conditions.opensAt)}</dd></div><div><dt>Cierre fijo</dt><dd>${fmt.dateTime(p.conditions.closesAt)}</dd></div><div><dt>Monto inicial</dt><dd>${fmt.uf(p.conditions.initialUF||0)}</dd></div><div><dt>Incremento</dt><dd>${fmt.uf(p.conditions.incrementUF||0)}</dd></div></dl></div></div>
  <div><form class="panel sticky-panel" data-form="decision" novalidate><h2>Lista de verificación</h2>${[['titular','Titularidad y autorización de publicación verificadas'],['antecedentes','Antecedentes legales revisados por Legal'],['fotos','Fotografías autorizadas y fieles, con texto alternativo'],['datos','Datos públicos correctos; sin datos privados'],['reglas','Reglas, fechas y montos del remate aprobados']].map(([k,l])=>h`<label class="form-check"><input type="checkbox" name="${k}"> <span>${l}</span></label>`)}
   ${p.completeness.ready?'':h`<p class="notice warn">Faltan: ${p.completeness.missing.join(', ')}.</p>`}<label class="form-field"><span>Motivo o comentario para el equipo</span><textarea name="reason" rows="3" placeholder="Obligatorio para pedir cambios o rechazar"></textarea></label>${p.hasPublicVersion?h`<label class="form-check"><input type="checkbox" name="withdrawPublic"> <span>Al pedir cambios o rechazar, retirar también la versión pública anterior.</span></label>`:''}
    <button type="button" class="btn btn-outline btn-block" data-action="task-new" data-link-path="/gestion/propiedades/${p.id}" data-link-label="${p.publicId} · ${p.title}">${icon('check')} Asignar tarea sobre este expediente</button><div class="stack"><button type="button" class="btn btn-primary" data-action="decide" data-value="approve" ${p.reviewStatus!=='in_review'?'disabled':''}>Aprobar y publicar</button><button type="button" class="btn btn-outline" data-action="decide" data-value="changes">Solicitar cambios</button><button type="button" class="btn btn-danger-outline" data-action="decide" data-value="reject">Rechazar</button></div><p class="hint">La decisión queda registrada con tu nombre, la versión y la lista de verificación, y se notifica al creador.</p></form></div></div>`,{lead:'Solo el Administrador general ve esta pantalla.'})}}});
actions.decide=async el=>{const form=$('form[data-form="decision"]');const d=formData(form);const action=el.dataset.value;const checklist={titular:d.titular,antecedentes:d.antecedentes,fotos:d.fotos,datos:d.datos,reglas:d.reglas};clearErrors(form);
 if(action==='approve'){if(!Object.values(checklist).every(Boolean))return showErrors(form,{message:'Completa la lista de verificación antes de publicar.'});const c=await confirmDialog({title:'Aprobar y publicar',text:`Se publicará la versión ${currentProp.submittedVersion} de "${currentProp.title}" con sus fotografías aprobadas y documentos autorizados. Los documentos privados seguirán privados. ${currentProp.auction&&currentProp.auction.status!=='closed'?'':'Se programará la subasta con las condiciones indicadas.'}`,confirm:'Publicar'});if(!c.ok)return}
 else if(d.reason.length<5)return showErrors(form,{message:'Indica el motivo para el equipo.',fields:{reason:'Indica el motivo (mínimo 5 caracteres).'}});
 try{await POST(`/api/v1/admin/reviews/${currentProp.id}/decision`,{action,reason:d.reason,checklist,withdrawPublic:!!d.withdrawPublic});clearDraft('decision');toast({approve:'Propiedad publicada.',changes:'Cambios solicitados al equipo.',reject:'Ficha rechazada.'}[action],'success');navigate('/gestion/revisiones')}catch(e){showErrors(form,e)}};

/* ---------- subastas: listado, ADM-14 monitor y ADM-15 adjudicación ---------- */
staffRoute('/gestion/remates',{title:'Subastas',roles:['operator'],view:async({path})=>{const r=await GET('/api/v1/admin/auctions');Live.accept({auctions:r.items.map(({property,award,...s})=>s)});
 return {title:'Subastas',html:staffShell(path,'Subastas',h`<p class="source-note">${r.viewers} espectadores conectados en total. Los montos los acepta el motor automáticamente; aquí supervisas, suspendes con motivo y confirmas resultados.</p><div class="table-wrap"><table class="responsive-table"><thead><tr><th>Subasta</th><th>Estado</th><th>Inicio</th><th>Cierre fijo</th><th>Monto vigente</th><th>Participación</th><th>Resultado</th><th><span class="visually-hidden">Acciones</span></th></tr></thead><tbody>${r.items.map(a=>h`<tr data-live-id="${a.id}"><td data-label="Subasta"><strong>${a.property?.title||'#'+a.id}</strong><br><small>#${a.id} · ${a.property?.publicId||''}</small></td><td data-label="Estado"><span class="status-pill" data-live="status" data-state="${a.status}">${STATUS_LABEL[a.status]}</span></td><td data-label="Inicio">${fmt.short(a.start)}</td><td data-label="Cierre">${fmt.short(a.end)}<br><small data-live="countdown">${Live.countdown(a)}</small></td><td data-label="Monto vigente" data-live="current-uf">${fmt.uf(a.currentMinor/100)}</td><td data-label="Participación"><span data-live="people">${Live.people(a)}</span><br><small><span data-live="bids">${a.totalBids}</span> registros</small></td><td data-label="Resultado">${a.award?AWARD_LABEL[a.award.status]:'—'}</td><td data-label="Acciones"><a class="btn btn-outline btn-sm" href="${href(`/gestion/remates/${a.id}/monitor`)}">Monitor</a>${a.status==='closed'?h` <a class="btn btn-outline btn-sm" href="${href(`/gestion/remates/${a.id}/resultado`)}">Resultado</a>`:''}</td></tr>`)}</tbody></table></div>`)}}});
let monitorTimer=null;
staffRoute('/gestion/remates/:id/monitor',{title:'Monitor',roles:['operator'],view:async({params})=>{const r=await GET(`/api/v1/admin/auctions/${params.id}/monitor`);Live.accept({auctions:[r.snapshot]});const a=r.snapshot;const s=Live.status(a);clearInterval(monitorTimer);monitorTimer=setInterval(()=>{if(!currentUrl().pathname.endsWith('/monitor'))return clearInterval(monitorTimer);GET(`/api/v1/admin/auctions/${params.id}/monitor`).then(x=>{const v=$('#viewerCount');if(v)v.textContent=x.viewers;if(x.snapshot.version!==Live.get(x.snapshot.id)?.version||$('#bidRows')?.dataset.count!=String(x.bids.length))render({keepScroll:true})}).catch(()=>{})},4000);
 return {title:'Monitor #'+a.id,html:staffShell('/gestion/remates','Monitor de subasta',h`<div class="monitor" data-live-id="${a.id}"><div class="metric-grid"><div class="metric"><small>Estado</small><strong data-live="status">${STATUS_LABEL[s]}</strong><em data-live="countdown">${Live.countdown(a)}</em></div><div class="metric"><small>Hora oficial del servidor</small><strong id="serverClock">${fmt.dateTime(Live.now())}</strong><em>Cierre fijo ${fmt.dateTime(a.end)}</em></div><div class="metric"><small>Monto vigente</small><strong data-live="current-uf">${fmt.uf(a.currentMinor/100)}</strong><em>Siguiente <span data-live="next-uf">${fmt.uf(a.nextMinor/100)}</span></em></div><div class="metric"><small>Cuentas que han subastado</small><strong>${a.participants}</strong><em>Espectadores conectados al sitio (sin cuenta necesaria): <span id="viewerCount">${r.viewers}</span></em></div><div class="metric"><small>Secuencia</small><strong>#${a.sequence}</strong><em>Versión ${a.version} · ${a.totalBids} registros</em></div></div>
  <div class="button-row">${['open','scheduled'].includes(s)?h`<button class="btn btn-danger" data-action="auction-op" data-op="suspend">Suspender con motivo</button>`:''}${s==='paused'?h`<button class="btn btn-dark" data-action="auction-op" data-op="resume">Reanudar con nueva fecha</button>`:''}${state.staff.roles.includes('general_admin')&&!['closed','cancelled'].includes(s)?h`<button class="btn btn-danger-outline" data-action="auction-op" data-op="cancel">Cancelar subasta</button>`:''}${s==='closed'?h`<a class="btn btn-primary" href="${href(`/gestion/remates/${a.id}/resultado`)}">Ver resultado preliminar</a>`:''}${r.property?h`<a class="btn btn-outline" href="/remates/${r.property.slug}" target="_blank" rel="noopener">Ver ficha pública</a><button class="btn btn-outline" data-action="task-new" data-link-path="/gestion/remates/${a.id}/monitor" data-link-label="Subasta #${a.id} · ${r.property.title}">${icon('check')} Asignar tarea</button>`:''}</div>
  <div class="columns"><div class="panel"><h2>Registros aceptados</h2><div class="table-wrap"><table class="responsive-table" id="bidRows" data-count="${r.bids.length}"><thead><tr><th>Secuencia</th><th>Folio</th><th>Hora oficial</th><th>Cuenta</th><th>Monto</th></tr></thead><tbody>${r.bids.map(b=>h`<tr><td data-label="Secuencia">#${b.sequence}</td><td data-label="Folio">${b.receipt}</td><td data-label="Hora">${fmt.dateTime(b.time)}</td><td data-label="Cuenta">${b.buyer}</td><td data-label="Monto">${fmt.uf(b.amountMinor/100)}</td></tr>`)}</tbody></table></div>${r.bids.length?'':h`<p>Aún no hay registros aceptados.</p>`}<p class="source-note">Los registros aceptados son inmutables. No existen contraofertas ni aprobación manual.</p></div>
  <div><div class="panel"><h2>Intentos rechazados</h2>${r.rejected.length?h`<ul class="activity">${r.rejected.map(x=>h`<li><div><strong>${x.code}</strong><small>${fmt.dateTime(x.at)} · ${x.buyer} · ${x.amountMinor?fmt.uf(x.amountMinor/100):'—'}</small><small>${x.message}</small></div></li>`)}</ul>`:h`<p>Sin rechazos.</p>`}</div><div class="panel"><h2>Eventos</h2>${r.events.length?h`<ol class="timeline">${r.events.slice().reverse().map(e=>h`<li><strong>${{suspended:'Suspendida',resumed:'Reanudada',cancelled:'Cancelada',scheduled:'Reprogramada'}[e.type]||e.type}</strong> · ${fmt.dateTime(e.time)}${e.reason?h`<br><small>${e.reason}</small>`:''}${e.end?h`<br><small>Nuevo cierre: ${fmt.dateTime(e.end)}</small>`:''}</li>`)}</ol>`:h`<p>Sin eventos administrativos.</p>`}</div></div></div></div>`,{lead:r.property?r.property.title+' · '+r.property.publicId:''}),
 after:()=>{const c=$('#serverClock');const t=setInterval(()=>{if(!document.contains(c))return clearInterval(t);c.textContent=fmt.dateTime(Live.now())},1000)}}}});
actions['auction-op']=async el=>{const op=el.dataset.op;const id=currentUrl().pathname.split('/')[3];const extra=op==='resume'?h`<label class="form-field"><span>Nuevo cierre fijo · hora de Chile</span><input type="datetime-local" id="dlgEnd" required></label>`:'';
 const c=await confirmDialog({title:{suspend:'Suspender subasta',resume:'Reanudar subasta',cancel:'Cancelar subasta'}[op],text:{suspend:'La recepción de montos se detiene de inmediato. El historial se conserva y se avisa a participantes y seguidores.',resume:'La subasta volverá a recibir montos hasta el nuevo cierre. Se avisará a participantes y seguidores.',cancel:'La subasta quedará cancelada y no recibirá montos. Esta acción no se puede deshacer.'}[op],confirm:'Confirmar',danger:op!=='resume',reason:true,reasonLabel:'Motivo (se informa a los participantes)',extra});if(!c.ok)return;
 const body={reason:c.reason};if(op==='resume'){const v=$('#dlgEnd',c.dialog)?.value;body.end=fromLocalInput(v)}
 try{await POST(`/api/v1/admin/auctions/${id}/${op}`,body);toast('Acción registrada y comunicada.','success');render({keepScroll:true})}catch(e){toast(e.message,'error')}};
staffRoute('/gestion/remates/:id/resultado',{title:'Adjudicación',roles:['operator'],view:async({params})=>{const r=await GET(`/api/v1/admin/auctions/${params.id}/result`);const w=r.award;const st=w?.status;
 const acts={pending_confirmation:[['confirm','Confirmar adjudicación','btn-primary'],['default','Registrar incumplimiento','btn-danger-outline']],offered_to_runner_up:[['confirm','Confirmar adjudicación al segundo oferente','btn-primary'],['default','Registrar incumplimiento','btn-danger-outline']],defaulted:[['offer_runner_up','Ofrecer al segundo oferente','btn-dark']]}[st]||[];
 return {title:'Adjudicación #'+params.id,html:staffShell('/gestion/remates','Resultado y adjudicación',h`${r.status!=='closed'?h`<p class="notice">${icon('clock')} La subasta aún no cierra. El resultado preliminar se calcula automáticamente al cierre fijo.</p>`:''}${w?h`<div class="panel"><h2>${AWARD_LABEL[st]}</h2><div class="columns"><div><h3>Mejor monto</h3>${r.best?h`<dl class="review-list"><div><dt>Cuenta</dt><dd>${r.best.buyer.name} · ${r.best.buyer.email||''}</dd></div><div><dt>Monto</dt><dd>${fmt.uf(r.best.amountMinor/100)}</dd></div><div><dt>Folio</dt><dd>${r.best.receipt}</dd></div></dl>`:h`<p>Sin ofertas válidas.</p>`}</div><div><h3>Segundo mejor oferente</h3>${r.runner?h`<dl class="review-list"><div><dt>Cuenta</dt><dd>${r.runner.buyer.name} · ${r.runner.buyer.email||''}</dd></div><div><dt>Monto</dt><dd>${fmt.uf(r.runner.amountMinor/100)}</dd></div><div><dt>Folio</dt><dd>${r.runner.receipt}</dd></div></dl>`:h`<p>No hay segundo oferente.</p>`}</div></div>
  ${acts.length?h`<form data-form="award" class="upload-box" novalidate><label class="form-field"><span>Motivo o nota (obligatorio salvo para confirmar)</span><textarea name="reason" rows="3"></textarea></label>${st==='defaulted'?h`<label class="form-check"><input type="checkbox" name="basesAllow"> <span>Confirmo que las bases aprobadas permiten ofrecer la adjudicación al segundo oferente.</span></label>`:''}<div class="button-row">${acts.map(([k,l,c])=>h`<button type="button" class="btn ${c}" data-action="award" data-value="${k}">${l}</button>`)}</div></form>`:''}
  <h3>Historial</h3><ol class="timeline">${w.history.slice().reverse().map(x=>h`<li><strong>${AWARD_LABEL[x.to]||x.to}</strong> · ${fmt.dateTime(x.at)}${x.reason?h`<br><small>${x.reason}</small>`:''}</li>`)}</ol></div>`:''}<p class="source-note">El resultado preliminar no es una adjudicación jurídica. La confirmación y una eventual gestión con el segundo oferente se rigen por las bases aprobadas. No hay gestión de garantías en esta versión.</p>`,{lead:r.property?.title||''})}}});
actions.award=async el=>{const form=$('form[data-form="award"]');const d=formData(form);const action=el.dataset.value;if(action!=='confirm'&&d.reason.length<5)return showErrors(form,{message:'Indica el motivo.',fields:{reason:'Indica el motivo.'}});const c=await confirmDialog({title:el.textContent,text:'La decisión quedará auditada y se notificará a la persona correspondiente.',confirm:'Confirmar'});if(!c.ok)return;try{await POST(`/api/v1/admin/auctions/${currentUrl().pathname.split('/')[3]}/award`,{action,reason:d.reason,basesAllow:!!d.basesAllow});clearDraft('award');toast('Resultado actualizado.','success');render({keepScroll:true})}catch(e){showErrors(form,e)}};

/* ---------- ADM-05 registro de actividad (aceptados y rechazados) ---------- */
let activityRows=[];
staffRoute('/gestion/ofertas',{title:'Actividad',roles:['operator'],view:async({path,query})=>{const qs=new URLSearchParams(Object.entries(query).filter(([,v])=>v));const r=await GET('/api/v1/admin/offers?'+qs);activityRows=r.items;
 return {title:'Actividad de subastas',html:staffShell(path,'Registro de actividad',h`<form class="toolbar" data-form="activity-filter" data-nodraft><label class="form-field"><span>Buscar</span><input name="q" value="${query.q||''}" placeholder="Folio, cuenta, propiedad o código"></label><label class="form-field"><span>Resultado</span><select name="result"><option value="">Todos</option><option value="accepted" ${query.result==='accepted'?'selected':''}>Aceptados</option><option value="rejected" ${query.result==='rejected'?'selected':''}>Rechazados</option></select></label><button class="btn btn-dark">Filtrar</button></form>
  ${r.items.length?h`<div class="table-wrap"><table class="responsive-table"><thead><tr><th>Hora del servidor</th><th>Referencia</th><th>Subasta</th><th>Cuenta</th><th>Monto</th><th>Resultado</th><th><span class="visually-hidden">Detalle</span></th></tr></thead><tbody>${r.items.map((x,i)=>h`<tr><td data-label="Hora">${fmt.dateTime(x.at)}</td><td data-label="Referencia">${x.receipt||x.id}</td><td data-label="Subasta">${x.property}</td><td data-label="Cuenta">${x.buyer}</td><td data-label="Monto">${x.amountMinor?fmt.uf(x.amountMinor/100):'—'}</td><td data-label="Resultado">${x.result==='accepted'?tag('Aceptado · #'+x.sequence,'ok'):tag('Rechazado · '+x.code,'bad')}</td><td data-label="Detalle"><button class="btn btn-outline btn-sm" data-action="activity-detail" data-index="${i}">Detalle</button></td></tr>`)}</tbody></table></div>`:h`<div class="empty-state"><p>Sin registros.</p></div>`}
  ${r.incidents.length?h`<div class="panel"><h2>Incidencias registradas</h2><ul class="activity">${r.incidents.map(n=>h`<li><div><strong>${n.ref}</strong><small>${fmt.dateTime(n.at)}</small><p>${n.note}</p>${n.visible?h`<small>Mensaje al comprador: ${n.visible}</small>`:''}</div></li>`)}</ul></div>`:''}`,{lead:'Bitácora privada del motor: cada intento con su resultado y motivo. Sin contraofertas ni aprobación de montos.'})}}});
forms['activity-filter']=form=>navigate('/gestion/ofertas?'+new URLSearchParams(Object.entries(formData(form)).filter(([,v])=>v)));
actions['activity-detail']=el=>{const x=activityRows[Number(el.dataset.index)];openDialog({title:'Detalle del registro',wide:true,body:h`<dl class="review-list"><div><dt>Referencia</dt><dd>${x.receipt||x.id}</dd></div><div><dt>Hora del servidor</dt><dd>${fmt.dateTime(x.at)}</dd></div><div><dt>Subasta</dt><dd>${x.property} (#${x.auctionId})</dd></div><div><dt>Cuenta</dt><dd>${x.buyer} ${x.buyerEmail?'· '+x.buyerEmail:''}</dd></div><div><dt>Monto</dt><dd>${x.amountMinor?fmt.uf(x.amountMinor/100):'—'}</dd></div><div><dt>Resultado</dt><dd>${x.result==='accepted'?'Aceptado':'Rechazado'} · ${x.code}${x.message?' · '+x.message:''}</dd></div><div><dt>Correlación</dt><dd>${x.requestId||'—'}</dd></div></dl>
 <form data-form="incident" data-ref="${x.receipt||x.id}" class="upload-box" novalidate><h3>Registrar incidencia</h3><label class="form-field"><span>Nota interna (no visible para el comprador)</span><textarea name="note" rows="3" required></textarea></label><label class="form-field"><span>Mensaje visible para el comprador (opcional)</span><textarea name="visible" rows="2"></textarea></label><button class="btn btn-dark">Registrar incidencia auditada</button></form>`})};
forms.incident=form=>submitWith(form,async d=>{await POST(`/api/v1/admin/offers/${encodeURIComponent(form.dataset.ref)}/events`,d);form.closest('dialog').close();toast('Incidencia registrada.','success');render({keepScroll:true})});

/* ---------- ADM-06 solicitudes ---------- */
let leadRows=[],leadStaff=[];
staffRoute('/gestion/solicitudes',{title:'Solicitudes',roles:['operator'],view:async({path,query})=>{const qs=new URLSearchParams(Object.entries(query).filter(([,v])=>v));const r=await GET('/api/v1/admin/leads?'+qs);leadRows=r.items;leadStaff=r.staff;
 return {title:'Solicitudes',html:staffShell(path,'Solicitudes',h`<div class="filters">${[['','Todas'],...Object.entries(LEAD_TYPE)].map(([k,v])=>h`<a class="chip ${(query.type||'')===k?'active':''}" href="${href('/gestion/solicitudes'+(k?'?type='+k:''))}" data-replace>${v}</a>`)}</div>
  ${r.items.length?h`<div class="table-wrap"><table class="responsive-table"><thead><tr><th>Código</th><th>Fecha</th><th>Tipo</th><th>Contacto</th><th>Detalle</th><th>Estado</th><th>Responsable</th><th><span class="visually-hidden">Acción</span></th></tr></thead><tbody>${r.items.map((l,i)=>h`<tr><td data-label="Código">${l.code}</td><td data-label="Fecha">${fmt.short(l.at)}</td><td data-label="Tipo">${LEAD_TYPE[l.type]}</td><td data-label="Contacto">${l.name}<br><small>${l.email||l.phone||''}</small></td><td data-label="Detalle"><small>${l.type==='seller'?[l.data?.type,l.data?.commune].filter(Boolean).join(' · '):l.data?.property||l.data?.topic||l.message||''}</small></td><td data-label="Estado">${tag(LEAD_STATUS[l.status],l.status==='new'?'warn':'')}</td><td data-label="Responsable">${l.assignedName||'Sin asignar'}</td><td data-label="Acción"><button class="btn btn-outline btn-sm" data-action="lead-open" data-index="${i}">Gestionar</button></td></tr>`)}</tbody></table></div>`:h`<div class="empty-state"><p>No hay solicitudes.</p></div>`}`,{lead:'Las solicitudes de venta nunca se convierten automáticamente en propiedades públicas.'})}}});
actions['lead-open']=el=>{const l=leadRows[Number(el.dataset.index)];const rows=Object.entries(l.data||{}).filter(([,v])=>v!=null&&v!=='');openDialog({title:`${LEAD_TYPE[l.type]} · ${l.code}`,wide:true,body:h`<dl class="review-list"><div><dt>Contacto</dt><dd>${l.name} · ${l.email||'—'} · ${l.phone||'—'} · prefiere ${l.preferred||'correo'}</dd></div><div><dt>Recibida</dt><dd>${fmt.dateTime(l.at)} · origen ${l.source||'—'}${l.campaign?' · campaña '+l.campaign:''}</dd></div>${rows.map(([k,v])=>h`<div><dt>${k}</dt><dd>${v}</dd></div>`)}${l.message?h`<div><dt>Mensaje</dt><dd>${l.message}</dd></div>`:''}<div><dt>Consentimiento</dt><dd>${l.consent?.contact?'Autoriza contacto':'—'}${l.consent?.marketing?' · acepta novedades':''}</dd></div></dl>
 ${l.type==='deletion'?h`<p class="notice">Para ejecutar la eliminación, anonimiza la cuenta desde <a href="${href('/gestion/usuarios?q='+encodeURIComponent(l.email))}" data-close>Usuarios y roles</a> (Administrador general).</p>`:''}
 <form data-form="lead-update" data-id="${l.id}" class="upload-box" novalidate><div class="field-grid"><label class="form-field"><span>Responsable</span><select name="assignedTo"><option value="">Sin asignar</option>${leadStaff.map(s=>h`<option value="${s.id}" ${l.assignedTo===s.id?'selected':''}>${s.name}</option>`)}</select></label><label class="form-field"><span>Estado</span><select name="status">${Object.entries(LEAD_STATUS).map(([k,v])=>h`<option value="${k}" ${l.status===k?'selected':''}>${v}</option>`)}</select></label></div><label class="form-field"><span>Nota interna</span><textarea name="note" rows="2"></textarea></label><label class="form-field"><span>Responder por correo (visible para la persona)</span><textarea name="reply" rows="2"></textarea></label><div class="button-row"><button class="btn btn-dark">Guardar gestión</button><button type="button" class="btn btn-outline" data-action="task-new" data-close data-title="Gestionar solicitud ${l.code}" data-link-path="/gestion/solicitudes" data-link-label="Solicitud ${l.code} · ${l.name}">${icon('check')} Asignar tarea</button>${l.phone?h`<a class="btn btn-wa" href="https://wa.me/${l.phone.replace(/\D/g,'').replace(/^9/,'569')}" target="_blank" rel="noopener">${icon('phone')} WhatsApp al contacto</a>`:''}</div></form>
 ${l.notes.length?h`<h3>Seguimiento</h3><ol class="timeline">${l.notes.map(n=>h`<li>${n.text}<br><small>${n.byName} · ${fmt.dateTime(n.at)}</small></li>`)}</ol>`:''}`})};
forms['lead-update']=form=>submitWith(form,async d=>{await PATCH('/api/v1/admin/leads/'+form.dataset.id,d);form.closest('dialog').close();toast('Gestión guardada.','success');render({keepScroll:true})});

/* ---------- ADM-07 usuarios y permisos ---------- */
let userRows=[],roleOptions=[];
staffRoute('/gestion/usuarios',{title:'Usuarios',roles:['general_admin'],view:async({path,query})=>{const r=await GET('/api/v1/admin/users?'+new URLSearchParams(Object.entries(query).filter(([,v])=>v)));userRows=r.items;roleOptions=r.roles;
 return {title:'Usuarios y permisos',html:staffShell(path,'Usuarios y permisos',h`<form class="toolbar" data-form="user-filter" data-nodraft><label class="form-field"><span>Buscar</span><input name="q" value="${query.q||''}" placeholder="Correo, nombre o ID"></label><label class="form-field"><span>Tipo</span><select name="type"><option value="">Todas</option><option value="internal" ${query.type==='internal'?'selected':''}>Equipo</option><option value="public" ${query.type==='public'?'selected':''}>Compradores</option></select></label><button class="btn btn-dark">Buscar</button></form>
  <div class="table-wrap"><table class="responsive-table"><thead><tr><th>Cuenta</th><th>Contacto</th><th>Tipo</th><th>Estado</th><th>Roles</th><th><span class="visually-hidden">Acciones</span></th></tr></thead><tbody>${r.items.map((u,i)=>h`<tr><td data-label="Cuenta"><strong>${u.name}</strong><br><small>${u.position||''}${u.area?' · '+u.area:''}</small></td><td data-label="Contacto"><small>${u.email}${u.whatsapp?h`<br>WhatsApp ${u.whatsapp}`:u.accountType==='internal'?h`<br><span class="warn">Sin WhatsApp</span>`:''}</small></td><td data-label="Tipo">${u.accountType==='internal'?'Equipo':'Comprador'}${u.mfa?h`<br><small>MFA activo</small>`:''}</td><td data-label="Estado">${tag({active:'Activa',pending:'Pendiente',blocked:'Bloqueada',deleted:'Eliminada'}[u.status],u.status==='active'?'ok':u.status==='blocked'?'bad':'')}${u.accountType==='public'?h`<br><small>${u.emailVerified?'Correo verificado':'Sin verificar'}</small>`:''}${u.deletionRequestedAt?h`<br><small class="warn">Pidió eliminación</small>`:''}</td><td data-label="Roles">${u.roleLabels.join(', ')}</td><td data-label="Acciones"><button class="btn btn-outline btn-sm" data-action="user-open" data-index="${i}" ${u.id===state.staff.id?'disabled':''}>Gestionar</button></td></tr>`)}</tbody></table></div>
  <form data-form="staff-create" class="panel" novalidate><h2>Crear usuario del equipo</h2><p>La persona recibe por correo y WhatsApp un enlace para activar su cuenta y crear su contraseña. El registro público nunca asigna roles internos.</p>
   <div class="field-grid"><label class="form-field"><span>Nombre y apellido *</span><input name="name" required autocomplete="off"></label><label class="form-field"><span>Correo *</span><input name="email" type="email" required autocomplete="off"></label></div>
   <div class="field-grid"><label class="form-field"><span>WhatsApp *</span><input name="whatsapp" type="tel" inputmode="tel" placeholder="+56 9 1234 5678" required></label><label class="form-field"><span>Cargo *</span><input name="position" required placeholder="Ej.: Ejecutiva comercial"></label></div>
   <div class="field-grid"><label class="form-field"><span>Área</span><select name="area"><option value="">Selecciona</option>${AREAS.map(a=>h`<option>${a}</option>`)}</select></label><label class="form-field"><span>Notas internas</span><input name="staffNotes" placeholder="Opcional: zona, horario, reemplazos"></label></div>
   <fieldset class="form-field" data-field="roles"><legend>Rol en la plataforma * <small>(puede tener más de uno)</small></legend><div class="check-grid">${ROLE_OPTIONS.map(([k,l])=>h`<label class="form-check"><input type="checkbox" name="role_${k}"> <span><strong>${l}</strong><br><small>${{general_admin:'Todo: aprueba y publica, usuarios y configuración. Usa código de verificación.',legal:'Antecedentes y documentos legales privados.',internal_contributor:'Crea fichas, sube fotos y solicita revisión.',operator:'Monitor de subastas, suspensión, actividad, solicitudes y adjudicación.',content_editor:'Blog: escribe, programa y publica.'}[k]}</small></span></label>`)}</div></fieldset>
   <button class="btn btn-primary">Crear usuario y enviar invitación</button></form>`,{lead:'Cada cambio de rol o estado exige motivo y queda en la auditoría.'})}}});
forms['user-filter']=form=>navigate('/gestion/usuarios?'+new URLSearchParams(Object.entries(formData(form)).filter(([,v])=>v)));
forms['staff-create']=form=>submitWith(form,async d=>{const roles=Object.keys(d).filter(k=>k.startsWith('role_')&&d[k]).map(k=>k.slice(5));const r=await POST('/api/v1/admin/users',{name:d.name,email:d.email,whatsapp:d.whatsapp,position:d.position,area:d.area,staffNotes:d.staffNotes,roles});form.reset();clearDraft('staff-create');teamCache=null;inviteResult(r,'Usuario creado');render({keepScroll:true})});
function inviteResult(r,title){openDialog({title,body:h`<p><strong>${r.user?.name||''}</strong> ${r.user?h`· ${r.user.email}`:''}</p><p>Enviamos la invitación por correo${r.user?.whatsapp||r.whatsappLink?' y WhatsApp':''}. El enlace vence en 72 horas.</p><label class="form-field"><span>Enlace de activación</span><input value="${r.activationLink}" readonly data-nodraft onclick="this.select()"></label><div class="button-row"><button class="btn btn-outline btn-sm" data-action="copy" data-value="${r.activationLink}">Copiar enlace</button>${r.whatsappLink?h`<a class="btn btn-wa btn-sm" href="${r.whatsappLink}" target="_blank" rel="noopener">${icon('phone')} Enviar por WhatsApp</a>`:''}</div>`})}
actions.copy=async el=>{try{await navigator.clipboard.writeText(el.dataset.value);toast('Copiado.','success')}catch{toast('No se pudo copiar; selecciona el texto.','error')}};
actions['user-open']=el=>{const u=userRows[Number(el.dataset.index)];openDialog({title:u.name,wide:u.accountType==='internal',body:h`<p>${u.email} · ${u.accountType==='internal'?'Cuenta del equipo':'Comprador'}${u.status==='pending'?' · invitación pendiente':''}${u.lastLoginAt?' · último ingreso '+fmt.rel(u.lastLoginAt):''}</p>
 ${u.accountType==='internal'?h`<form data-form="staff-edit" data-id="${u.id}" class="upload-box" novalidate><h3>Datos del integrante</h3><div class="field-grid"><label class="form-field"><span>Nombre</span><input name="name" value="${u.name}" required></label><label class="form-field"><span>WhatsApp</span><input name="whatsapp" type="tel" value="${u.whatsapp}" required></label></div><div class="field-grid"><label class="form-field"><span>Cargo</span><input name="position" value="${u.position}"></label><label class="form-field"><span>Área</span><select name="area"><option value="">—</option>${AREAS.map(a=>h`<option ${u.area===a?'selected':''}>${a}</option>`)}</select></label></div><label class="form-field"><span>Notas internas</span><input name="staffNotes" value="${u.staffNotes||''}"></label><div class="button-row"><button class="btn btn-dark">Guardar datos</button>${u.status==='pending'?h`<button type="button" class="btn btn-outline" data-action="resend-invite" data-id="${u.id}">Reenviar invitación</button>`:''}${u.whatsapp?h`<button type="button" class="btn btn-outline" data-action="task-new" data-close data-title="">Asignar tarea</button>`:''}</div></form><h3>Estado y roles</h3>`:''}<form data-form="user-action" data-id="${u.id}" class="stack" novalidate><label class="form-field"><span>Acción</span><select name="action">${u.status==='blocked'?h`<option value="unblock">Desbloquear</option>`:h`<option value="block">Bloquear y cerrar sesiones</option>`}${u.accountType==='internal'?h`<option value="grant">Asignar rol</option><option value="revoke">Revocar rol</option>`:''}${u.accountType==='public'&&u.status!=='deleted'?h`<option value="anonymize">Anonimizar (ejecutar eliminación de datos)</option>`:''}</select></label>${u.accountType==='internal'?h`<label class="form-field"><span>Rol</span><select name="role">${roleOptions.map(r=>h`<option value="${r.key}">${r.label}${u.roles.includes(r.key)?' (actual)':''}</option>`)}</select></label>`:''}<label class="form-field"><span>Motivo</span><textarea name="reason" rows="2" required></textarea></label><button class="btn btn-dark">Aplicar cambio</button></form>`})};
forms['staff-edit']=form=>submitWith(form,async d=>{await PATCH(`/api/v1/admin/users/${form.dataset.id}/profile`,d);form.closest('dialog')?.close();teamCache=null;toast('Datos actualizados.','success');render({keepScroll:true})});
actions['resend-invite']=async el=>{try{const r=await POST(`/api/v1/admin/users/${el.dataset.id}/resend-invite`);el.closest('dialog')?.close();inviteResult(r,'Invitación reenviada')}catch(e){toast(e.message,'error')}};
forms['user-action']=form=>submitWith(form,async d=>{if(d.action==='anonymize'){const c=await confirmDialog({title:'Anonimizar cuenta',text:'Se reemplazarán nombre, correo y teléfono, se cerrarán sus sesiones y se quitarán sus guardadas. Los montos históricos se conservan sin datos personales.',confirm:'Anonimizar',danger:true});if(!c.ok)return}await PATCH('/api/v1/admin/users/'+form.dataset.id,d);form.closest('dialog')?.close();toast('Cambio aplicado y auditado.','success');render({keepScroll:true})});

/* ---------- ADM-08 configuración (incluye Google Analytics 4) ---------- */
staffRoute('/gestion/configuracion',{title:'Configuración',roles:['general_admin'],view:async({path})=>{const {config:c,properties}=await GET('/api/v1/admin/config');const reasonField=h`<label class="form-field"><span>Motivo del cambio *</span><input name="reason" required minlength="5" placeholder="Queda registrado en el historial"></label>`;
 return {title:'Configuración',html:staffShell(path,'Configuración',h`
  <form data-form="config" data-section="ga" class="panel" novalidate><h2>Google Analytics 4</h2><p>Pega el ID de medición del flujo web de GA4 (Administrar › Flujos de datos › Web). Las etiquetas solo se cargan si la persona acepta cookies de analítica. Nunca se envían montos ni datos de contacto.</p><div class="field-grid"><label class="form-field"><span>ID de medición</span><input name="gaMeasurementId" value="${c.gaMeasurementId}" placeholder="G-XXXXXXXXXX" pattern="G-[A-Z0-9]{6,12}"></label><label class="form-check"><input type="checkbox" name="gaDebug" ${c.gaDebug?'checked':''}> <span>Modo depuración (DebugView y consola)</span></label></div>${reasonField}<button class="btn btn-dark">Guardar analítica</button><p class="hint">Eventos configurados: page_view, view_home, search_submitted, filters_applied, property_viewed, property_saved, share, registration_started, sign_up, registration_completed, login, offer_started, offer_submitted, seller_form_started, seller_form_submitted, generate_lead, blog_article_viewed, document_downloaded, currency_changed. Detalle en docs/plan-de-medicion.md.</p></form>
  <div class="panel" id="correoPanel"><h2>Correo</h2><p class="hint">Cargando el estado del proveedor…</p></div>
  <form data-form="config" data-section="uf" class="panel" novalidate><h2>Valor UF y conversión</h2><div class="field-grid"><label class="form-field"><span>Valor CLP por UF</span><input name="ufValue" type="number" step="0.01" value="${c.ufValue}"></label><label class="form-field"><span>Fecha de vigencia</span><input name="ufDate" type="date" value="${c.ufDate}"></label></div><label class="form-field"><span>Fuente</span><input name="ufSource" value="${c.ufSource}"></label><label class="form-check"><input type="checkbox" name="ufIsDemo" ${c.ufIsDemo?'checked':''}> <span>Es un valor ficticio de demostración (se rotula como tal)</span></label><p class="hint">Si la fecha no es la de hoy y no es un valor de demostración, el sitio muestra “equivalencia no disponible” y mantiene los montos en UF.</p>${reasonField}<button class="btn btn-dark">Guardar UF</button></form>
  <form data-form="config" data-section="home" class="panel" novalidate><h2>Inicio y destacados</h2><label class="form-field"><span>Titular</span><input name="homeTitle" value="${c.homeTitle}" maxlength="90"></label><label class="form-field"><span>Bajada</span><textarea name="homeLead" rows="2" maxlength="240">${c.homeLead}</textarea></label><fieldset class="form-field"><legend>Remates destacados (máximo 6, en este orden)</legend><div class="check-grid">${properties.map(p=>h`<label class="form-check"><input type="checkbox" name="feat_${p.id}" ${c.featured.includes(p.id)?'checked':''}> <span>${p.title}</span></label>`)}</div></fieldset>${reasonField}<button class="btn btn-dark">Guardar inicio</button></form>
  <form data-form="config" data-section="contact" class="panel" novalidate><h2>Datos de contacto públicos</h2><div class="field-grid"><label class="form-field"><span>Correo</span><input name="cEmail" value="${c.contact.email}"></label><label class="form-field"><span>Teléfono</span><input name="cPhone" value="${c.contact.phone}"></label><label class="form-field"><span>Instagram</span><input name="cInstagram" value="${c.contact.instagram}"></label><label class="form-field"><span>Horario</span><input name="cHours" value="${c.contact.hours}"></label></div><h3>Redes sociales del pie de página</h3><p class="hint">Deja vacío un campo para ocultar su ícono.</p><div class="field-grid">${[['facebook','Facebook'],['instagram','Instagram'],['tiktok','TikTok'],['linkedin','LinkedIn']].map(([k,l])=>h`<label class="form-field"><span>${l}</span><input name="s_${k}" type="url" value="${(c.social||{})[k]||''}" placeholder="https://"></label>`)}</div>${reasonField}<button class="btn btn-dark">Guardar contacto y redes</button></form>
  <form data-form="config" data-section="how" class="panel" novalidate><h2>Cómo funciona</h2><label class="form-field"><span>Título</span><input name="hTitle" value="${c.how.title}"></label><label class="form-field"><span>Bajada</span><input name="hLead" value="${c.how.lead}"></label><label class="form-field"><span>Propósito</span><textarea name="hPurpose" rows="2">${c.how.purpose}</textarea></label><label class="form-field"><span>Pasos (uno por línea: Título | Descripción)</span><textarea name="hSteps" rows="5">${c.how.steps.map(s=>s.join(' | ')).join('\n')}</textarea></label><label class="form-field"><span>Valores aprobados (uno por línea)</span><textarea name="hValues" rows="4">${c.how.values.join('\n')}</textarea></label>${reasonField}<button class="btn btn-dark">Guardar contenido</button></form>
  <form data-form="config" data-section="faqs" class="panel" novalidate><h2>Preguntas frecuentes</h2><label class="form-field"><span>Una por línea: Pregunta | Respuesta</span><textarea name="faqs" rows="8">${c.faqs.map(f=>f.q+' | '+f.a).join('\n')}</textarea></label>${reasonField}<button class="btn btn-dark">Guardar preguntas</button></form>
  <form data-form="config" data-section="legal" class="panel" novalidate><h2>Textos legales versionados</h2><label class="form-field"><span>Documento</span><select name="legalKey">${Object.entries(c.legal).map(([k,v])=>h`<option value="${k}">${v.title} (versión ${v.version})</option>`)}</select></label><label class="form-field"><span>Nueva versión</span><input name="legalVersion" placeholder="Ej.: 2026-11"></label><label class="form-field"><span>Texto (admite ## títulos y listas con -)</span><textarea name="legalBody" rows="8" data-legal-bodies="${JSON.stringify(Object.fromEntries(Object.entries(c.legal).map(([k,v])=>[k,v.body])))}">${c.legal.privacidad.body}</textarea></label><p class="hint">Si cambias los términos, define la nueva versión de bases: las cuentas deberán aceptarla antes de su próximo monto en subastas nuevas.</p>${reasonField}<button class="btn btn-dark">Publicar nueva versión</button></form>
  <div class="panel"><h2>Historial de cambios</h2>${c.history.length?h`<ol class="timeline">${c.history.map(x=>h`<li>${fmt.dateTime(x.at)} · ${x.keys.join(', ')}<br><small>${x.reason}</small></li>`)}</ol>`:h`<p>Sin cambios registrados.</p>`}</div>`,{lead:'Los secretos técnicos no se administran aquí: se configuran en el entorno seguro del servidor.'}),
 after:root=>{loadMailPanel(c);const f=$('form[data-section="legal"]',root);const bodies=JSON.parse(f.legalBody.dataset.legalBodies);f.legalKey.addEventListener('change',()=>{f.legalBody.value=bodies[f.legalKey.value]})}}}});
async function loadMailPanel(c){const box=$('#correoPanel');if(!box)return;let st;try{st=await GET('/api/v1/admin/mail/status')}catch(e){box.innerHTML=toHtml(h`<h2>Correo</h2><p class="notice warn">${e.message}</p>`);return}
 const cur=(c.mailFrom||'').match(/<([^>]+)>/)?.[1]||'';const curName=(c.mailFrom||'').replace(/\s*<.*$/,'')||'SeSubasta';
 box.innerHTML=toHtml(h`<h2>Correo</h2>${st.provider==='none'?h`<p class="notice warn">${icon('alert')} No hay proveedor conectado: los correos solo se ven en /dev/correos. Guarda la clave con <code>npx wrangler secret put BREVO_API_KEY</code>.</p>`:st.connected===false?h`<p class="notice warn">${icon('alert')} ${st.error||'No se pudo conectar con el proveedor.'}</p>`:h`<p class="notice success">${icon('check')} ${st.provider==='brevo'?'Brevo':'Resend'} conectado${st.account?h` · cuenta <strong>${st.account}</strong>${st.company?' ('+st.company+')':''}`:''}. ${st.active?h`Enviando desde <strong>${st.from}</strong>.`:'Falta elegir el remitente.'}</p>`}
 ${st.provider!=='none'&&st.connected!==false?h`<form data-form="config" data-section="mail" novalidate><div class="field-grid"><label class="form-field"><span>Correo remitente</span>${st.senders?.length?h`<select name="mailFromEmail"><option value="">Selecciona</option>${st.senders.map(s=>h`<option value="${s.email}" ${s.email===cur?'selected':''} ${s.active?'':raw('disabled')}>${s.email}${s.active?'':' (sin verificar)'}</option>`)}</select>`:h`<input name="mailFromEmail" type="email" value="${cur}">`}<small class="hint">Solo aparecen los remitentes de la cuenta de Brevo conectada; deben estar verificados.</small></label><label class="form-field"><span>Nombre visible</span><input name="mailFromName" value="${curName}"></label></div><label class="form-field"><span>Motivo del cambio *</span><input name="reason" required minlength="5" value="Configurar remitente de correos"></label><button class="btn btn-dark">Guardar remitente</button></form>
 ${st.active?h`<form data-form="mail-test" class="upload-box" novalidate><label class="form-field"><span>Enviar correo de prueba a</span><input name="to" type="email" value="${state.staff.email}"></label><button class="btn btn-primary">Enviar prueba</button></form>`:''}`:''}`)}
forms['mail-test']=form=>submitWith(form,async d=>{const r=await POST('/api/v1/admin/mail/test',{to:d.to});toast('Correo de prueba enviado a '+r.to+'. Revisa también spam.','success')});
forms.config=form=>submitWith(form,async d=>{const s=form.dataset.section;let body={reason:d.reason};
 if(s==='mail')body={...body,mailFromEmail:d.mailFromEmail,mailFromName:d.mailFromName};
 if(s==='ga')body={...body,gaMeasurementId:d.gaMeasurementId.toUpperCase(),gaDebug:d.gaDebug};
 if(s==='uf')body={...body,ufValue:d.ufValue,ufDate:d.ufDate,ufSource:d.ufSource,ufIsDemo:d.ufIsDemo};
 if(s==='home')body={...body,homeTitle:d.homeTitle,homeLead:d.homeLead,featured:Object.keys(d).filter(k=>k.startsWith('feat_')&&d[k]).map(k=>Number(k.slice(5)))};
 if(s==='contact')body={...body,contact:{email:d.cEmail,phone:d.cPhone,instagram:d.cInstagram,hours:d.cHours},social:{facebook:d.s_facebook,instagram:d.s_instagram,tiktok:d.s_tiktok,linkedin:d.s_linkedin}};
 if(s==='how')body={...body,how:{title:d.hTitle,lead:d.hLead,purpose:d.hPurpose,steps:d.hSteps.split('\n').map(l=>l.split('|').map(x=>x.trim())).filter(x=>x[0]&&x[1]),values:d.hValues.split('\n').map(x=>x.trim()).filter(Boolean)}};
 if(s==='faqs')body={...body,faqs:d.faqs.split('\n').map(l=>{const i=l.indexOf('|');return {q:l.slice(0,i).trim(),a:l.slice(i+1).trim()}}).filter(f=>f.q&&f.a)};
 if(s==='legal'){if(!d.legalVersion)throw new ApiError(422,{message:'Indica la nueva versión.',fields:{legalVersion:'Indica la nueva versión.'}});body=d.legalKey==='terminos'?{...body,termsVersion:d.legalVersion,termsBody:d.legalBody}:{...body,legal:{[d.legalKey]:{body:d.legalBody,version:d.legalVersion}}}}
 await PATCH('/api/v1/admin/config',body);clearDraft('config');state.config=await GET('/api/v1/config');Analytics.init(state.config);toast('Configuración guardada.','success');render({keepScroll:true})});

/* ---------- ADM-11 gestión del blog y ADM-12 editor ---------- */
staffRoute('/gestion/blog',{title:'Blog',roles:['content_editor'],view:async({path,query})=>{const r=await GET('/api/v1/admin/blog/posts?'+new URLSearchParams(Object.entries(query).filter(([,v])=>v)));
 return {title:'Blog',html:staffShell(path,'Blog editorial',h`<div class="filters">${[['','Todos'],...Object.entries(POST_LABEL)].map(([k,v])=>h`<a class="chip ${(query.status||'')===k?'active':''}" href="${href('/gestion/blog'+(k?'?status='+k:''))}" data-replace>${v}</a>`)}</div>
  <div class="table-wrap"><table class="responsive-table"><thead><tr><th>Título</th><th>Estado</th><th>Categoría</th><th>Autor</th><th>Actualización</th><th>Publicación</th><th><span class="visually-hidden">Acciones</span></th></tr></thead><tbody>${r.items.map(p=>h`<tr><td data-label="Título"><strong>${p.title}</strong><br><small>/blog/${p.slug}</small></td><td data-label="Estado">${tag(POST_LABEL[p.status],p.status==='published'?'ok':p.status==='scheduled'?'warn':'')}</td><td data-label="Categoría">${r.categories.find(c=>c.id===p.categoryId)?.name||'—'}</td><td data-label="Autor">${p.authorName}</td><td data-label="Actualización">${fmt.short(p.updatedAt)}</td><td data-label="Publicación">${p.status==='scheduled'?'Programado '+fmt.short(p.scheduledAt):p.publishedAt?fmt.short(p.publishedAt):'—'}</td><td data-label="Acciones"><a class="btn btn-outline btn-sm" href="${href('/gestion/blog/'+p.id)}">Editar</a>${p.status==='published'?h` <a class="btn btn-outline btn-sm" href="/blog/${p.slug}" target="_blank" rel="noopener">Ver</a>`:''}</td></tr>`)}</tbody></table></div>
  <div class="panel"><h2>Categorías</h2><ul class="activity">${r.categories.map(c=>h`<li><div><strong>${c.name}</strong><small>/blog/categoria/${c.slug} · ${c.active?'activa':'inactiva'}</small></div><button class="btn btn-outline btn-sm" data-action="cat-toggle" data-id="${c.id}" data-active="${c.active}">${c.active?'Desactivar':'Activar'}</button></li>`)}</ul><form data-form="category" class="toolbar" novalidate><label class="form-field"><span>Nueva categoría</span><input name="name" required></label><label class="form-field"><span>Descripción</span><input name="description"></label><button class="btn btn-dark">Crear</button></form></div>`,{lead:'Crea, revisa, programa y publica artículos. La publicación editorial nunca publica propiedades.',actions:h`<a class="btn btn-primary" href="${href('/gestion/blog/nuevo')}">+ Nuevo artículo</a>`})}}});
forms.category=form=>submitWith(form,async d=>{await POST('/api/v1/admin/blog/categories',d);clearDraft('category');toast('Categoría creada.','success');render({keepScroll:true})});
actions['cat-toggle']=async el=>{try{await PATCH('/api/v1/admin/blog/categories/'+el.dataset.id,{active:el.dataset.active!=='true'});render({keepScroll:true})}catch(e){toast(e.message,'error')}};
let editingPost=null;
staffRoute('/gestion/blog/:id',{title:'Editor',roles:['content_editor'],view:async({params})=>{let p,cats;if(params.id==='nuevo'){const r=await GET('/api/v1/admin/blog/posts');cats=r.categories;p={id:null,title:'',slug:'',excerpt:'',body:'',cover:{key:'',alt:'',url:''},categoryId:cats[0]?.id,tags:[],seoTitle:'',metaDescription:'',canonical:'',noindex:false,status:'draft',featured:false}}else{const r=await GET('/api/v1/admin/blog/posts/'+params.id);p=r.post;cats=r.categories}editingPost=p;
 return {title:p.title||'Nuevo artículo',html:staffShell('/gestion/blog',p.id?'Editar artículo':'Nuevo artículo',h`<div class="prop-status">${tag(POST_LABEL[p.status],p.status==='published'?'ok':'')} ${p.status==='scheduled'?h`<span>Se publicará el ${fmt.dateTime(p.scheduledAt)}</span>`:''}</div>
  <div class="columns"><form data-form="post" class="panel" novalidate data-id="${p.id||''}"><label class="form-field"><span>Título (H1) *</span><input name="title" value="${p.title}" required maxlength="140"></label><label class="form-field"><span>URL</span><input name="slug" value="${p.slug}" placeholder="se genera desde el título"><small class="hint">${p.status==='published'?'Si cambias la URL de un artículo publicado se crea una redirección 301 desde la anterior.':'/blog/…'}</small></label>
   <label class="form-field"><span>Extracto o bajada *</span><textarea name="excerpt" rows="2" maxlength="300">${p.excerpt}</textarea></label><label class="form-field"><span>Texto * <small>Usa “## ” para subtítulos, “- ” para listas, **negrita** y [enlace](/remates)</small></span><textarea name="body" rows="16" data-preview>${p.body}</textarea></label>
   <fieldset class="form-field"><legend>Foto de portada *</legend><input type="hidden" name="coverKey" value="${p.cover.key}"><div class="cover-pick">${p.cover.url?h`<img src="${p.cover.url}" alt="" width="200" height="120" id="coverPreview">`:h`<img id="coverPreview" alt="" hidden width="200" height="120">`}<div><label class="form-field"><span>Subir imagen (JPG, PNG o WebP, máx. 3 MB)</span><input type="file" name="coverFile" accept="image/jpeg,image/png,image/webp" data-action-upload="cover"></label><label class="form-field"><span>O elegir imagen ilustrativa de muestra</span><select name="coverDemo"><option value="">—</option>${Array.from({length:20},(_,i)=>h`<option value="demo:${i+1}" ${p.cover.key==='demo:'+(i+1)?'selected':''}>Imagen ${i+1}</option>`)}</select></label></div></div><label class="form-field"><span>Texto alternativo de la portada *</span><input name="coverAlt" value="${p.cover.alt}"></label></fieldset>
   <div class="field-grid"><label class="form-field"><span>Categoría *</span><select name="categoryId">${cats.map(c=>h`<option value="${c.id}" ${p.categoryId===c.id?'selected':''}>${c.name}</option>`)}</select></label><label class="form-field"><span>Etiquetas (separadas por coma)</span><input name="tags" value="${(p.tags||[]).join(', ')}"></label></div>
   <h3>SEO</h3><label class="form-field"><span>Título SEO <small data-counter="seoTitle">${p.seoTitle.length}/65</small></span><input name="seoTitle" value="${p.seoTitle}" maxlength="65" data-count="65"></label><label class="form-field"><span>Meta descripción <small data-counter="metaDescription">${p.metaDescription.length}/160</small></span><textarea name="metaDescription" rows="2" maxlength="160" data-count="160">${p.metaDescription}</textarea></label><label class="form-field"><span>Canonical (opcional)</span><input name="canonical" value="${p.canonical}" placeholder="https://…"></label><label class="form-check"><input type="checkbox" name="noindex" ${p.noindex?'checked':''}> <span>No indexar (noindex)</span></label><label class="form-check"><input type="checkbox" name="featured" ${p.featured?'checked':''}> <span>Destacar en el inicio</span></label>
   <div class="button-row"><button class="btn btn-dark">Guardar borrador</button>${p.id?h`<button type="button" class="btn btn-outline" data-action="post-status" data-value="review">Enviar a revisión</button><button type="button" class="btn btn-outline" data-action="post-schedule">Programar</button><button type="button" class="btn btn-primary" data-action="post-status" data-value="publish">${p.status==='published'?'Actualizar publicación':'Publicar'}</button>${p.status==='published'||p.status==='scheduled'?h`<button type="button" class="btn btn-outline" data-action="post-status" data-value="draft">Despublicar</button>`:''}<button type="button" class="btn btn-danger-outline" data-action="post-status" data-value="archive">Archivar</button>`:''}</div>${p.id?'':h`<p class="hint">Guarda el borrador para poder publicarlo o programarlo.</p>`}</form>
  <div class="panel sticky-panel"><div class="preview-head"><h2>Vista previa</h2><div class="view-toggle" role="group" aria-label="Ancho de vista previa"><button class="chip active" data-action="preview-width" data-value="desktop" aria-pressed="true">Escritorio</button><button class="chip" data-action="preview-width" data-value="mobile" aria-pressed="false">Móvil</button></div></div><div id="postPreview" class="post-preview"></div><h3>Vista en buscadores y redes</h3><div id="socialPreview" class="social-preview"></div></div></div>`),
 after:root=>{const f=$('form[data-form="post"]',root);const upd=()=>{const d=formData(f);$('#postPreview').innerHTML=toHtml(h`<article class="prose"><span class="blog-tag">${cats.find(c=>c.id===d.categoryId)?.name||''}</span><h1>${d.title||'Título del artículo'}</h1><p class="lead">${d.excerpt}</p>${md(d.body)}</article>`);$('#socialPreview').innerHTML=toHtml(h`<p class="sp-url">remates.sesubasta.cl/blog/${d.slug||slug(d.title)}</p><p class="sp-title">${d.seoTitle||d.title}</p><p class="sp-desc">${d.metaDescription||d.excerpt}</p>`)};f.addEventListener('input',upd);upd();
  $$('[data-count]',f).forEach(el=>el.addEventListener('input',()=>{$(`[data-counter="${el.name}"]`,f).textContent=el.value.length+'/'+el.dataset.count}));
  f.coverDemo.addEventListener('change',()=>{if(!f.coverDemo.value)return;f.coverKey.value=f.coverDemo.value;const im=$('#coverPreview');im.hidden=false;im.src=`assets/propiedades/propiedad-${String(f.coverDemo.value.slice(5)).padStart(2,'0')}.webp`;saveDraft(f.coverKey)});
  f.coverFile.addEventListener('change',async()=>{const file=f.coverFile.files[0];if(!file)return;if(file.size>3e6)return toast('La imagen supera 3 MB.','error');try{const r=await POST('/api/v1/admin/blog/media',{file:await readFile(file)});f.coverKey.value=r.key;f.coverDemo.value='';const im=$('#coverPreview');im.hidden=false;im.src=r.url;toast('Imagen subida. Recuerda escribir el texto alternativo.','success')}catch(e){toast(e.message,'error')}})}}}});
const postBody=d=>({title:d.title,slug:d.slug,excerpt:d.excerpt,body:d.body,cover:{key:d.coverKey,alt:d.coverAlt},categoryId:d.categoryId,tags:d.tags.split(',').map(t=>t.trim()).filter(Boolean),seoTitle:d.seoTitle,metaDescription:d.metaDescription,canonical:d.canonical,noindex:d.noindex,featured:d.featured});
forms.post=form=>submitWith(form,async d=>{const id=form.dataset.id;const r=id?await PATCH('/api/v1/admin/blog/posts/'+id,postBody(d)):await POST('/api/v1/admin/blog/posts',postBody(d));clearDraft('post');toast('Borrador guardado.','success');if(!id)navigate('/gestion/blog/'+r.post.id,{replace:true});else render({keepScroll:true})});
async function postStatus(action,at){const f=$('form[data-form="post"]');try{await PATCH('/api/v1/admin/blog/posts/'+editingPost.id,postBody(formData(f)));await POST(`/api/v1/admin/blog/posts/${editingPost.id}/publish`,{action,at});clearDraft('post');toast({publish:'Artículo publicado. El sitemap se actualizó.',schedule:'Artículo programado.',review:'Enviado a revisión.',draft:'Artículo despublicado.',archive:'Artículo archivado.'}[action],'success');render({keepScroll:true})}catch(e){showErrors(f,e)}}
actions['post-status']=el=>postStatus(el.dataset.value);
actions['post-schedule']=async()=>{const c=await confirmDialog({title:'Programar publicación',text:'Elige la fecha y hora de publicación (hora de Chile).',confirm:'Programar',extra:h`<label class="form-field"><span>Fecha y hora</span><input type="datetime-local" id="dlgAt" required></label>`});if(!c.ok)return;postStatus('schedule',fromLocalInput($('#dlgAt',c.dialog)?.value))};
actions['preview-width']=el=>{$$('[data-action="preview-width"]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',String(b===el))});$('#postPreview').classList.toggle('mobile',el.dataset.value==='mobile')};

/* ---------- auditoría ---------- */
staffRoute('/gestion/auditoria',{title:'Auditoría',roles:['general_admin'],view:async({path,query})=>{const r=await GET('/api/v1/admin/audit?'+new URLSearchParams(Object.entries(query).filter(([,v])=>v)));
 return {title:'Auditoría',html:staffShell(path,'Bitácora de acciones',h`<form class="toolbar" data-form="audit-filter" data-nodraft><label class="form-field"><span>Buscar</span><input name="q" value="${query.q||''}" placeholder="Acción, persona o ID"></label><label class="form-field"><span>Entidad</span><select name="entity"><option value="">Todas</option>${['property','auction','user','post','lead','config','attempt','category','media'].map(e=>h`<option ${query.entity===e?'selected':''}>${e}</option>`)}</select></label><button class="btn btn-dark">Filtrar</button></form>
  <div class="table-wrap"><table class="responsive-table"><thead><tr><th>Fecha</th><th>Actor</th><th>Acción</th><th>Entidad</th><th>Detalle</th></tr></thead><tbody>${r.items.map(a=>h`<tr><td data-label="Fecha">${fmt.dateTime(a.at)}</td><td data-label="Actor">${a.actor}</td><td data-label="Acción"><code>${a.action}</code></td><td data-label="Entidad">${a.entity} · ${a.entityId}</td><td data-label="Detalle"><small>${Object.entries(a.changes||{}).filter(([k])=>k!=='before').map(([k,v])=>`${k}: ${typeof v==='object'?JSON.stringify(v):v}`).join(' · ')}</small></td></tr>`)}</tbody></table></div>`,{lead:'Accesos, publicaciones, cambios de estado, roles, configuración y decisiones. Sin contraseñas ni tokens.'})}}});
forms['audit-filter']=form=>navigate('/gestion/auditoria?'+new URLSearchParams(Object.entries(formData(form)).filter(([,v])=>v)));
